using System;using System.Reflection;using System.Windows;using System.Windows.Controls;using CodexStrip;
class RenderTest {[STAThread] static int Main(){var app=new Application();var w=new StripWindow(true);try{w.Show();w.Demo();w.Render();var grid=(Grid)typeof(StripWindow).GetField("cards",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(w);var first=grid.Children[0];w.Engine.LastRefresh=DateTime.Now;w.Render();if(!object.ReferenceEquals(first,grid.Children[0]))throw new Exception("Identical cards were rebuilt on timestamp refresh");Console.WriteLine("PASS: unchanged card controls preserved across sync timestamp update");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}finally{w.Close();}}}
